package dev.aivillages.e2e.paralleld;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import dev.aivillages.core.kernel.logistics.*;
import static dev.aivillages.core.kernel.logistics.TransferObservation.*;
public final class DChestCourierGameTests {
 @GameTest(maxTicks=10000,structure="cognitivecraft_parallel_d_tests:mobility")
 public void exactGuardedCourierPreservesStockAndRefusesInterference(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();DChestCourierScene.open(h.getLevel(),h.absolutePos(new BlockPos(0,2,0)),p,Path.of(System.getProperty("cognitivecraft.parallelD.evidence")),"D08-GT01",s->h.runAfterDelay(10,()->{s.reset("SUCCESS_Q4",Items.OAK_PLANKS,4,10,3,2);var w=s.withdraw();h.assertTrue(w.status()==Status.LIVE_WITHDRAWN && w.after().equals(new Counts(6,7,2)),"exact native pickup4 preserves old3");s.travel();move(h,s,()->{var deposited=s.deposit();h.assertTrue(deposited.status()==Status.LIVE_DEPOSITED && deposited.after().equals(new Counts(6,3,6)) && s.session.phase()==DeliveryPolicy.Phase.DELIVERED_LIVE,"exact native courier6/3/6");s.home();move(h,s,()->controls(h,s));});}));}
 static void move(GameTestHelper h,DChestCourierScene s,Runnable next){var m=s.tick();if(m.terminal()){h.assertTrue(m.status()==MobilityObservation.Status.ARRIVED,"native courier movement "+m);next.run();}else h.runAfterDelay(1,()->move(h,s,next));}
 static void controls(GameTestHelper h,DChestCourierScene s){
  s.reset("SOURCE_EFFECT_BOUNDARY",Items.OAK_PLANKS,4,10,3,2);var calls=new java.util.concurrent.atomic.AtomicInteger();var adversarial=new dev.aivillages.fabric.logistics.MinecraftTransferAdapter(s.level,s.arena.actor,s.arena.identity,s.scope,s.reader,(key,order)->{if(calls.incrementAndGet()==2){s.source().getItem(0).shrink(1);s.source().setChanged();}return new dev.aivillages.fabric.logistics.MinecraftTransferAdapter.Control(s.arena.identity,true,true,s.custodyRevision);});var raced=adversarial.withdraw(s.session,s.source,s.destination,new ItemStack(Items.OAK_PLANKS),null);h.assertTrue(raced.observation().reason()==Reason.INTERFERENCE && s.source().getItem(0).getCount()==9 && s.arena.actor.getInventory().getItem(0).getCount()==3 && s.arena.actor.getInventory().getItem(1).isEmpty(),"source mutation at final authority boundary zero adapter effect");s.session.observe(raced.observation());s.frame("SOURCE_CHANGED_BEFORE_EFFECT",raced.observation());
  s.reset("OLD_STOCK_INTERFERENCE",Items.OAK_PLANKS,4,10,3,2);s.withdraw();var moved=s.arena.actor.getInventory().getItem(s.batch.slot());s.arena.actor.getInventory().setItem(s.batch.slot(),ItemStack.EMPTY);s.arena.actor.getInventory().setItem(2,moved);s.custodyRevision++;s.frame("EXTERNAL_MOVED_BATCH",null);var refused=s.transfer.deposit(s.batch);h.assertTrue(refused.status()==Status.REFUSED,"old stock cannot discharge attributed batch");s.session.observe(refused);s.frame("REFUSED",refused);
  s.reset("NO_DISJOINT_SLOT",Items.OAK_PLANKS,4,10,3,2);for(int i=1;i<8;i++)s.arena.actor.getInventory().setItem(i,new ItemStack(Items.OAK_PLANKS));s.frame("FILLED_CARRIER",null);var noSlot=s.withdraw();h.assertTrue(noSlot.reason()==Reason.NO_DISJOINT_SLOT && s.source().getItem(0).getCount()==10,"no disjoint slot zero mutation");
  s.reset("FULL_DESTINATION",Items.OAK_PLANKS,4,10,3,2);for(int i=0;i<27;i++)s.destination().setItem(i,new ItemStack(Items.STONE,64));s.frame("FILLED_DESTINATION",null);h.assertTrue(s.withdraw().reason()==Reason.CAPACITY && s.source().getItem(0).getCount()==10,"complete batch capacity before withdraw");
  s.reset("CUSTOM_COMPONENTS",Items.OAK_PLANKS,4,10,3,2);s.source().getItem(0).set(DataComponents.CUSTOM_NAME,Component.literal("non-default"));s.frame("COMPONENT_CHANGED",null);h.assertTrue(s.withdraw().status()==Status.REFUSED && s.source().getItem(0).getCount()==10,"native nondefault components refused before mutation");
  selected(h,s,()->quantity(h,s,1,()->quantity(h,s,64,()->batches(h,s))));
 }
 static void selected(GameTestHelper h,DChestCourierScene s,Runnable next){s.reset("SELECTED_SOURCE_SLOT",Items.OAK_PLANKS,4,10,3,2,false,true);var stack=s.source().getItem(0);var member=s.source.topology().members().getFirst().incarnation();long tick=s.level.getGameTime();
  var expired=new dev.aivillages.fabric.logistics.MinecraftTransferAdapter.Selected(s.source.storage(),member,0,stack,10,tick-41,s.scope.principal());var denied=s.transfer.withdraw(s.session,s.source,s.destination,new ItemStack(Items.OAK_PLANKS),(id,item,t)->expired);h.assertTrue(denied.observation().reason()==Reason.SELECTION_REQUIRED && s.source().getItem(0).getCount()==10,"expired explicit slot witness cannot withdraw");s.frame("EXPIRED_SELECTION",denied.observation());
  var good=new dev.aivillages.fabric.logistics.MinecraftTransferAdapter.Selected(s.source.storage(),member,0,stack,10,tick,s.scope.principal());var w=s.transfer.withdraw(s.session,s.source,s.destination,new ItemStack(Items.OAK_PLANKS),(id,item,t)->good);h.assertTrue(w.observation().status()==Status.LIVE_WITHDRAWN,"valid selected slot still works");s.batch=w.batch();s.session.observe(w.observation());s.frame("WITHDRAW",w.observation());s.travel();move(h,s,()->{h.assertTrue(s.deposit().status()==Status.LIVE_DEPOSITED,"selected-slot courier");s.home();move(h,s,next);});
 }
 static void quantity(GameTestHelper h,DChestCourierScene s,int q,Runnable next){s.reset("SUCCESS_Q"+q,Items.OAK_PLANKS,q,64,3,2);var w=s.withdraw();h.assertTrue(w.status()==Status.LIVE_WITHDRAWN && w.quantity()==q,"exact admitted quantity");s.travel();move(h,s,()->{var x=s.deposit();h.assertTrue(x.status()==Status.LIVE_DEPOSITED && x.after().equals(new Counts(64-q,3,2+q)),"exact q"+q+" native conservation");s.home();move(h,s,next);});}
 static void batches(GameTestHelper h,DChestCourierScene s){s.reset("SUCCESS_BATCH4",Items.ENDER_PEARL,64,64,3,2);batch(h,s);}
 static void batch(GameTestHelper h,DChestCourierScene s){var w=s.withdraw();h.assertTrue(w.status()==Status.LIVE_WITHDRAWN && w.quantity()==16,"complete bounded16-unit native batch");s.travel();move(h,s,()->{var p=s.deposit();h.assertTrue(p.status()==Status.LIVE_DEPOSITED,"native batch deposit");boolean more=s.session.remaining()>0;s.home();move(h,s,()->{if(more)batch(h,s);else{h.assertTrue(s.session.batches()==4 && s.session.delivered()==64,"four batches one original delivery");fullInFlight(h,s);}});});}
 static void fullInFlight(GameTestHelper h,DChestCourierScene s){s.reset("FULL_IN_FLIGHT",Items.OAK_PLANKS,4,10,3,2);s.withdraw();s.travel();move(h,s,()->{for(int i=0;i<27;i++)s.destination().setItem(i,new ItemStack(Items.STONE,64));s.destination().setChanged();s.frame("FILLED_TARGET_MIDFLIGHT",null);var x=s.deposit();h.assertTrue(x.reason()==Reason.CAPACITY && s.arena.actor.getInventory().getItem(s.batch.slot()).getCount()==4 && s.session.delivered()==0,"full target preserves actual in-flight4");h.assertTrue(s.transfer.deposit(s.batch).reason()==Reason.UNKNOWN_CUSTODY,"refused native token cannot replay without J settlement");s.home();move(h,s,()->revoked(h,s));});}
 static void revoked(GameTestHelper h,DChestCourierScene s){s.reset("REVOKED_IN_FLIGHT",Items.OAK_PLANKS,4,10,3,2);s.withdraw();s.travel();move(h,s,()->s.revoke(()->h.runAfterDelay(1,()->{var result=s.deposit();h.assertTrue(result.reason()==Reason.UNAUTHORIZED && s.arena.actor.getInventory().getItem(s.batch.slot()).getCount()==4 && s.session.delivered()==0,"real ACL revoke preserves4 in carrier");s.identities.close();DChestCourierScene.when(s.level,s.store.closeAsync(),v->h.runAfterDelay(1,h::succeed));})));}
}
